head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_EntprGrpList_OnLoadError
 * @description dts_EntprGrpList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_EntprGrpList_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_EntprGrpList);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.dts_EntprGrpList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_EntprGrpList_OnLoadCompleted
 * @description dts_EntprGrpList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_EntprGrpList_OnLoadCompleted = function(rowcount) {
    try {
        // 데이터셋 OnLoadCompleted
        if (dts_EntprGrpList.errorMsg) {
            alert(dts_EntprGrpList.errorMsg);
        } else {
            txb_TotCnt.setValue("총 " + rowcount + " 건");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00103.dts_EntprGrpList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_EntprGrpList_OnDblClick
 * @description grd_EntprGrpList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_EntprGrpList_OnDblClick = async function(row, colid) {
    try {
        // 그리드 더블클릭
        await scwin.setParam(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.grd_EntprGrpList_OnDblClick" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Close_onclick = async function() {
    try {
        // 닫기버튼 클릭
        await scwin.closeFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Confirm_onclick = async function() {
    try {
        // 확인버튼 클릭
        await scwin.setParam();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.img_Confirm_onclick" });
    }
};

/**
 * @method
 * @name txb_EntprGrpNm_onkeydown
 * @description txb_EntprGrpNm 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_EntprGrpNm_onkeydown = async function() {
    try {
        // 기업집단명 엔터
        if (event.keyCode === 13) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.txb_EntprGrpNm_onkeydown" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // 조회 버튼 클릭
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00103.btn_Search_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 기업목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_EntprGrpList",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_EntprGrpList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_EntprGrpList.removeAll();
    txb_TotCnt.setValue("");
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    if (txb_EntprGrpNm.getValue() === "") {
        alert("기업집단명을 입력하세요.");
        txb_EntprGrpNm.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {*} v_Currow v_Currow
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParam = async function(v_Currow) {
    if (v_Currow === undefined) {
        v_Currow = dts_EntprGrpList.getRowPosition();
    }
    let arrPar = new Array();
    arrPar[0] = {
        ENTPR_GRP_CD: dts_EntprGrpList.getCellData(v_Currow, "ENTPR_GRP_CD"), // 기업집단코드
        ENTPR_GRP_NM: dts_EntprGrpList.getCellData(v_Currow, "ENTPR_GRP_NM") // 기업집단명
    };

    opener.fn_SetParAffCoCd(arrPar);
    await scwin.closeFrame();
};

/**
 * @method
 * @name closeFrame
 * @description close frame
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.closeFrame = async function() {
    await $c.win.closePopup();
};

/**
 * @method
 * @name gform_onload
 * @description form onload
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // form onload
    $c.libRoundPanel.PanelToGroupBox(panel_Top); // 패널라운드 처리

    let arrPar = opener.fn_GetParAffCoCd();
    txb_EntprGrpNm.setValue(arrPar[0]);
    if (txb_EntprGrpNm.getValue() !== "") {
        await scwin.search();
    } else {
        txb_EntprGrpNm.focus();
    }
};
